'use strict';
const D=window.DEMO_DATA,L=window.DemoLogic;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n/100);
const pct=n=>n==null?'—':(n*100).toFixed(1)+'%';
const tag=(text,type='neutral')=>`<span class="tag ${type}">${esc(text)}</span>`;
let state={ledger:{},audit:[]};try{const saved=JSON.parse(localStorage.getItem('flinn-pulse-v1'));if(saved&&saved.ledger&&Array.isArray(saved.audit))state=saved;}catch(e){}
let view='revenue',tier='All',tour=-1,answer=Object.keys(D.answers)[0];
const headings={revenue:['ARR Truth','One reference. Every discrepancy.','Finance and CRM, reconciled at the account level.'],product:['Product & Event QA','Track value. Trust the signal.','Feature adoption and event governance, from the same data foundation.'],actions:['Automations','The right action starts with evidence.','Explainable review proposals, with controlled delivery simulation.'],copilot:['SQL Copilot','Ask clearly. Verify the answer.','Natural-language questions with visible, reviewed SQL.']};
const tours=[
 {view:'revenue',title:'Open with the business problem',text:'I built Flinn Pulse to demonstrate the responsibilities in this role. These are 25 fictional accounts. Finance is the chosen reporting reference, and every CRM discrepancy remains visible rather than being overwritten.'},
 {view:'revenue',title:'Explain the financial model',text:'The bridge reconciles opening ARR plus new, expansion, contraction and churn to ending ARR. The model uses integer EUR cents and one record per account. New accounts are excluded from the starting-cohort retention calculation.'},
 {view:'product',title:'Show why event governance matters',text:'The tracking contract defines five permitted events. One malformed event is quarantined. Adoption uses a meaningful threshold and eligible accounts, and the Mid-Market gap-analysis feature has low adoption that deserves investigation.'},
 {view:'actions',title:'Connect an insight to a reviewed action',text:'Four high-value accounts have a substantial usage drop before renewal. This rule proposes a review, not a churn prediction. I can inspect the evidence, approve the proposal and simulate delivery. Repeating delivery skips the duplicate.'},
 {view:'copilot',title:'Show the copilot and SQL boundary',text:'Without an API key, the Python app maps seven supported question types to reviewed queries and executes them in DuckDB. The browser edition shows those verified query results. Custom SQL and optional provider generation run in the Streamlit app.'},
 {view:'copilot',title:'Close with what you would do next',text:'The source includes five modular models, automated checks, dbt configuration and deployment files. Production work would connect approved sources, agree Finance policy, add authentication and a durable queue, and validate the alerts with the teams using them.'}
];
function selected(rows){return tier==='All'?rows:rows.filter(r=>r.tier===tier);}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">No records for this selection.</td></tr>`}</tbody></table></div>`;}
function kpi(label,value,hint,cl=''){return `<div class="kpi"><div class="label">${label}</div><div class="value ${cl}">${value}</div><div class="hint">${hint}</div></div>`;}
function panel(title,subtitle,body,extra=''){return `<section class="panel"><div class="row-heading"><div><h2>${title}</h2><div class="subtitle">${subtitle}</div></div>${extra}</div>${body}</section>`;}
function usageAccounts(){const map={};for(const r of selected(D.adoption)){if(!map[r.account_id])map[r.account_id]={...r,current_events:0,previous_events:0};map[r.account_id].current_events+=r.current_events;map[r.account_id].previous_events+=r.previous_events;}return Object.values(map).map(r=>({...r,change:r.previous_events?(r.current_events-r.previous_events)/r.previous_events:null}));}
function renderRevenue(){
 const rows=selected(D.arr),m=L.revenue(rows),issues=rows.filter(r=>r.reconciliation_status!=='Reconciled');
 const bridge=[['October ARR',m.start,''],['New business',m.newBusiness,'add'],['Expansion',m.expansion,'add'],['Contraction',m.contraction,'subtract'],['Churn',m.churn,'subtract'],['November ARR',m.end,'']].map(([name,n,cls])=>`<div class="bridge-step ${cls}"><span>${name}</span><strong>${n>0&&cls==='add'?'+':''}${euro(n)}</strong><span>${name==='November ARR'?(m.reconciles?'Bridge reconciles':'Check bridge'):'Annual recurring EUR'}</span></div>`).join('');
 const byTier=['Enterprise','Mid-Market','Growth'].map(t=>[t,rows.filter(r=>r.tier===t).reduce((n,r)=>n+r.arr_cents,0)]).filter(r=>r[1]>0),max=Math.max(...byTier.map(r=>r[1]),1);
 const tierChart=`<div class="chart">${byTier.map(([t,n])=>`<div class="bar-wrap"><span class="bar-value">${euro(n)}</span><div class="bar current" style="height:${n/max*115}px"></div></div>`).join('')}</div><div class="chart-labels">${byTier.map(([t])=>`<span>${t}</span>`).join('')}</div>`;
 const signals=issues.map(r=>`<div class="signal"><div class="signal-icon">!</div><div><div class="signal-title">${esc(r.account_name)}</div><small>${r.reconciliation_status==='ARR mismatch'?`CRM differs by ${euro(r.variance_cents)}`:'Missing close date on closed-won deal'}</small></div></div>`).join('')||'<p class="empty">All selected accounts reconcile.</p>';
 const sorted=[...rows].sort((a,b)=>(a.reconciliation_status==='Reconciled')-(b.reconciliation_status==='Reconciled')||b.arr_cents-a.arr_cents);
 const ledger=table(['Account / tier','Finance ARR','CRM ARR','Variance','Status'],sorted.map(r=>[`<strong>${esc(r.account_name)}</strong><small>${esc(r.tier)}</small>`,euro(r.arr_cents),euro(r.crm_arr_cents),`<span class="${r.variance_cents?'negative':''}">${euro(r.variance_cents)}</span>`,tag(r.reconciliation_status,r.reconciliation_status==='Reconciled'?'teal':r.variance_cents?'red':'amber')]));
 return `<div class="hero"><div><h2>Revenue you can trace. Differences you can resolve.</h2><p>One annualised recurring-revenue reference, with a visible path back to Finance and CRM. Source conflicts stay open for review.</p></div><span class="hero-chip">${m.active} active accounts · EUR</span></div><div class="grid kpis">${kpi('Finance reference ARR',euro(m.end),`${euro(m.delta)} movement vs October`)}${kpi('ARR discrepancies',m.mismatches,'Account-level CRM / Finance conflicts',m.mismatches?'negative':'positive')}${kpi('Net revenue retention',pct(m.nrr),'Starting cohort · excludes new accounts')}${kpi('Gross revenue retention',pct(m.grr),'Starting cohort · excludes expansion')}</div>${panel('ARR movement bridge','October to November 2026 · account-level contract snapshots',`<div class="bridge-list">${bridge}</div><div class="chart-note">Opening ARR + new business + expansion − contraction − churn = ending ARR. ${m.reconciles?'Verified against the account-level mart.':''}</div>`)}<div class="grid two-col even">${panel('ARR by account tier','Current Finance reference · excludes one-off fees',tierChart)}${panel('Reporting exceptions',`${issues.length} records require source review`,signals,`<button class="link-button" data-go="actions">Review proposals</button>`)}</div>${panel('Account-level reconciliation','Sorted to surface exceptions first · current contract snapshots',ledger,`<button class="button small" id="export-arr">Export CSV</button>`)}<div class="explainer"><strong>Metric policy:</strong> Finance invoice data is a synthetic, already annualised recurring contract equivalent. Overdue payment alone does not remove contracted ARR. CRM rows are total contract snapshots, not additive deal line items. No source is corrected automatically.</div>`;
}
function renderProduct(){
 const rows=selected(D.adoption),eligible=new Set(rows.map(r=>r.account_id)).size,features=[...new Set(D.adoption.map(r=>r.feature))];
 const adoption=features.map(f=>{const r=rows.filter(r=>r.feature===f);return {feature:f,n:r.filter(x=>x.adopted).length,total:r.length};});
 const featureTable=table(['Governed feature','Adopted / eligible','Adoption'],adoption.map(r=>[`<span class="mono" style="font-size:12px">${esc(r.feature)}</span>`,`${r.n} / ${r.total}`,tag(pct(r.total?r.n/r.total:0),r.total&&r.n/r.total<.2?'amber':'teal')]));
 const mm=D.adoption.filter(r=>r.tier==='Mid-Market'&&r.feature==='ai_gap_analysis_triggered');
 const usage=usageAccounts().sort((a,b)=>(a.change??1)-(b.change??1)),max=Math.max(...usage.map(r=>Math.max(r.current_events,r.previous_events)),1);
 const chart=usage.slice(0,7).map(r=>`<div class="usage-row"><span>${esc(r.account_name)}</span><div class="usage-track"><div style="width:${r.previous_events/max*100}%"></div><div style="width:${r.current_events/max*100}%"></div></div><strong class="${r.change<-.5?'negative':''}">${r.change===null?'New':pct(r.change)}</strong></div>`).join('');
 const checks=D.checks.map(c=>`<div class="check"><span class="check-symbol ${c.status==='FAIL'?(c.severity==='critical'?'fail':'warn'):''}">${c.status==='PASS'?'✓':'!'}</span><div><div class="check-title">${esc(c.name)}</div><p>${esc(c.description)}</p></div>${tag(c.status==='PASS'?'PASS':c.failing_rows+' failing',c.status==='PASS'?'teal':c.severity==='critical'?'red':'amber')}</div>`).join('');
 return `<div class="hero"><div><h2>Measure the workflow, not just the click.</h2><p>Five governed MedTech features, equal 30-day comparison windows and explicit adoption thresholds. Malformed events are quarantined before aggregation.</p></div><span class="hero-chip">3+ events = adoption</span></div><div class="grid kpis">${kpi('Eligible accounts',eligible,'Positive current recurring ARR')}${kpi('Governed features',features.length,'Explicit event-name allowlist')}${kpi('Quarantined events',1,'ClickedExportBtn violates the contract','negative')}${kpi('Mid-Market gap analysis',pct(mm.filter(r=>r.adopted).length/mm.length),'Whole portfolio · 1 of 8 active accounts','negative')}</div><div class="grid two-col even">${panel('Feature adoption',`${tier==='All'?'All tiers':esc(tier)} · current 30 days`,featureTable)}${panel('Usage shifts to investigate','Oct 26–Nov 24 vs Sep 26–Oct 25 · 7 accounts shown',`<div class="legend"><i></i> Previous 30 days <i class="curr"></i> Current 30 days</div>${chart}`)}</div>${panel('Data quality checks','Whole warehouse · 8 invariant checks pass; 4 deliberately injected source/business checks fail',checks)}<div class="explainer"><strong>Tracking contract:</strong> event_id, account_id, user_id, event_name, timestamp and duration_sec. Current window: 26 Oct–24 Nov. Previous: 26 Sep–25 Oct. Timestamps use UTC. ${D.raw_events.toLocaleString()} raw events become ${D.clean_events.toLocaleString()} valid events. Raw records remain available for investigation.</div>`;
}
function renderActions(){
 const alerts=selected(D.alerts),recorded=alerts.filter(a=>state.ledger[a.event_id]==='Recorded locally').length;
 const cards=alerts.map(a=>{const status=state.ledger[a.event_id]||'Needs review';return `<article class="action-card"><div>${tag(a.rule==='renewal_usage_risk'?'Customer Success':a.rule==='feature_underadoption'?'Product':'Revenue quality',a.rule==='renewal_usage_risk'?'amber':'neutral')}<h3>${esc(a.title)} · ${esc(a.account_name)}</h3><p>${esc(a.evidence)}</p><small class="legend">Owner: ${esc(a.owner)} · Event ${a.event_id.slice(0,8)}</small></div><div class="action-controls">${tag(status,status==='Recorded locally'?'teal':'neutral')}<button class="button small" data-payload="${a.event_id}">Inspect payload</button><button class="button small" data-action="approve" data-id="${a.event_id}" ${status!=='Needs review'?'disabled':''}>Approve</button><button class="button small primary" data-action="record" data-id="${a.event_id}" ${!['Approved','Recorded locally'].includes(status)?'disabled':''}>${status==='Recorded locally'?'Retry simulation':'Simulate delivery'}</button></div></article>`;}).join('');
 const audit=state.audit.slice(-8).reverse().map(a=>`<div class="audit"><strong>${esc(a.result)}</strong> · ${esc(a.account)}<br/><span>${esc(a.time)} · ${esc(a.id.slice(0,12))}</span></div>`).join('')||'<p class="empty">Approve a proposal to start the review trail.</p>';
 return `<div class="hero"><div><h2>Every action has evidence and an owner.</h2><p>Review a proposed action, approve it, then simulate delivery. Stable event IDs prevent a repeated delivery from being recorded twice in this browser.</p></div><span class="hero-chip">Review required</span></div><div class="grid kpis">${kpi('Review proposals',alerts.length,'Transparent rules, no hidden score')}${kpi('Renewal usage signals',alerts.filter(a=>a.rule==='renewal_usage_risk').length,'High ARR · renewal ≤45 days · usage ↓50%')}${kpi('Feature review signals',alerts.filter(a=>a.rule==='feature_underadoption').length,'Mid-Market adoption below 20%')}${kpi('Recorded locally',recorded,'Delivery simulation · no outbound traffic','positive')}</div>${panel('Proposed actions','Human review comes before simulated delivery',cards||'<p class="empty">No proposals for this selection.</p>',`<button class="button small" id="export-alerts">Download payloads</button>`)}<div class="grid two-col even">${panel('Rule definitions','Heuristics for investigation, not churn predictions',`<div class="rule-box"><strong>Renewal review</strong><br/>ARR ≥ €60,000 · renewal within 45 days · previous events ≥10 · current events down ≥50%.<br/><br/><strong>Feature review</strong><br/>Mid-Market feature adoption below 20%.<br/><br/><strong>Revenue review</strong><br/>Nonzero CRM / Finance variance, or required close date missing.</div>`)}${panel('Review audit','Local browser state · resettable demo ledger',audit,`<button class="link-button" id="reset-ledger">Reset simulation</button>`)}</div><div class="explainer"><strong>Delivery boundary:</strong> payloads include a Slack Block Kit message and an n8n-compatible JSON envelope. No Slack or n8n service is connected. This browser uses local storage; the Streamlit app uses session state. Production needs a durable queue, authentication, retry policy and monitoring.</div>`;
}
function renderCopilot(){
 const result=D.answers[answer],rows=result.rows,headers=rows.length?Object.keys(rows[0]):[],answerTable=table(headers.map(esc),rows.map(r=>headers.map(h=>esc(typeof r[h]==='number'?new Intl.NumberFormat('en-IE',{maximumFractionDigits:2}).format(r[h]):String(r[h]??'—').slice(0,70)))));
 const models=Object.keys(D.lineage),opts=models.map(m=>`<option>${esc(m)}</option>`).join('');
 return `<div class="hero"><div><h2>A question becomes a query you can inspect.</h2><p>Seven supported questions, answered from the same cleaned warehouse. No API key is needed to demonstrate the flow.</p></div><span class="hero-chip">Reviewed SQL templates</span></div><section class="panel" style="margin:20px 0"><h2>Ask the data</h2><div class="subtitle">Browser edition: verified query snapshots from the Python pipeline. Tier filter does not apply to this tab.</div><form id="question-form"><label for="question" class="small-label">Choose a question or type a supported variation</label><div style="display:flex;gap:10px;margin:10px 0"><input id="question" value="${esc(answer)}" list="suggestions" style="flex:1;min-width:0;border:1px solid #cbd8e3;border-radius:6px;padding:12px;font-size:14px"><button class="button primary" type="submit">Answer</button></div><datalist id="suggestions">${Object.keys(D.answers).map(q=>`<option value="${esc(q)}"></option>`).join('')}</datalist></form><div style="display:flex;flex-wrap:wrap;gap:7px;margin:15px 0">${Object.keys(D.answers).map((q,i)=>`<button class="button small" data-question="${i}">${esc(q.replace('Which ','').replace('What is our ','').replace('Show ',''))}</button>`).join('')}</div><div id="question-notice"></div><div class="small-label">${esc(answer)} · Deterministic mode</div><pre class="code">${esc(result.sql)}</pre><div style="margin-top:17px">${answerTable}</div><button class="button small" id="export-answer" style="margin-top:15px">Export answer CSV</button></section><div class="grid two-col even">${panel('The data path','Same models power the Streamlit app and this browser snapshot',`<div class="pipeline"><div class="pipeline-node"><span>EXTRACT</span><strong>Synthetic sources</strong><small>CRM deals, invoices, product events</small></div><div class="pipeline-node"><span>LOAD</span><strong>DuckDB</strong><small>Raw records retained for inspection</small></div><div class="pipeline-node"><span>TRANSFORM</span><strong>Modular SQL</strong><small>3 staging models + 2 marts</small></div><div class="pipeline-node"><span>CHECK</span><strong>Data contracts</strong><small>12 checks + dbt invariants</small></div><div class="pipeline-node"><span>DECIDE</span><strong>BI & copilot</strong><small>Visible definitions and SQL</small></div><div class="pipeline-node"><span>ACT</span><strong>Review queue</strong><small>Stable IDs and simulated delivery</small></div></div>`)}${panel('Run the full Python application','Source includes Streamlit, Plotly and a live DuckDB query sandbox',`<pre class="code">python -m venv .venv\n# Activate your virtual environment\npip install -r requirements.txt\nstreamlit run app.py</pre><p style="font-size:12px;color:var(--muted)">Optional Gemini/OpenAI SQL generation is disabled unless a key is configured and the user opts in. Generated SQL goes through the same validator. Provider mode has not been tested with live credentials.</p><a class="button primary" href="https://github.com/abhishekrahul93/flinn-pulse/archive/refs/heads/main.zip" download>Download complete source</a>`)}</div>${panel('Inspect an actual SQL model','dbt-compatible files executed by the Python pipeline',`<select class="code-select" id="model-select" aria-label="SQL model">${opts}</select><pre id="model-code" class="code">${esc(D.lineage[models[0]])}</pre>`)}<div class="explainer"><strong>Python query boundary:</strong> one SELECT against two marts; allowlisted functions; isolated in-memory database with external access disabled; 100-row output cap; query timeout and bounded memory. Browser answers are precomputed by those same queries. Free-form SQL runs in the downloadable Streamlit app.</div>`;
}
function render(){
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const h=headings[view];$('crumb').textContent=h[0];$('page-title').textContent=h[1];$('page-description').textContent=h[2];$('issue-count').textContent=D.checks.filter(c=>c.status==='FAIL').length;
 $('content').innerHTML=({revenue:renderRevenue,product:renderProduct,actions:renderActions,copilot:renderCopilot})[view]();renderTour();bindView();
}
function go(v){view=v;history.replaceState(null,'','#'+v);render();window.scrollTo({top:0,behavior:'smooth'});}
function renderTour(){const el=$('tour');el.classList.toggle('hidden',tour<0);if(tour<0)return;const step=tours[tour];el.innerHTML=`<div class="tour-heading"><div><div class="small-label">PRESENTATION MODE · ${tour+1} / ${tours.length}</div><h2>${step.title}</h2></div><div class="tour-controls"><button class="button small" id="tour-back" ${tour===0?'disabled':''}>Previous</button><button class="button small primary" id="tour-next">${tour===tours.length-1?'Finish':'Next'}</button><button class="button small" id="tour-close">Close</button></div></div><p class="quote">“${step.text}”</p>`;$('tour-back').onclick=()=>{tour--;go(tours[tour].view)};$('tour-next').onclick=()=>{tour++;if(tour===tours.length){tour=-1;render()}else go(tours[tour].view)};$('tour-close').onclick=()=>{tour=-1;render()};}
function save(){try{localStorage.setItem('flinn-pulse-v1',JSON.stringify(state));}catch(e){toast('Local storage unavailable; state lasts for this page only.');}}
let toastTimer;function toast(text){$('toast').textContent=text;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),4000);}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){if(!rows.length)return '';const keys=Object.keys(rows[0]),cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';return [keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n');}
function bindView(){
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
 if($('export-arr'))$('export-arr').onclick=()=>download('arr_reconciliation.csv',csv(selected(D.arr)),'text/csv');
 if($('export-alerts'))$('export-alerts').onclick=()=>download('review_payloads.json',JSON.stringify(selected(D.alerts).map(a=>a.payload),null,2));
 if($('reset-ledger'))$('reset-ledger').onclick=()=>{state={ledger:{},audit:[]};save();render();toast('Simulation reset. Source data was unchanged.');};
 document.querySelectorAll('[data-payload]').forEach(b=>b.onclick=()=>{const a=D.alerts.find(a=>a.event_id===b.dataset.payload);$('detail-content').innerHTML=`<h2>${esc(a.title)}</h2><p>${esc(a.account_name)} · ${esc(a.owner)}</p><pre class="code">${esc(JSON.stringify(a.payload,null,2))}</pre><button class="button primary" id="download-payload">Download JSON</button>`;$('download-payload').onclick=()=>download('pulse_'+a.event_id+'.json',JSON.stringify(a.payload,null,2));$('detail').showModal();});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=D.alerts.find(a=>a.event_id===b.dataset.id),current=state.ledger[a.event_id]||'Needs review',r=L.transition(current,b.dataset.action);state.ledger[a.event_id]=r.status;state.audit.push({id:a.event_id,account:a.account_name,result:r.result,time:new Date().toLocaleTimeString()});save();render();toast(r.result==='duplicate_skipped'?'Duplicate skipped. This action was already recorded.':r.result==='approved'?'Approved. Delivery still requires simulation.':'Recorded in this browser. No message was sent.');});
 if($('model-select'))$('model-select').onchange=e=>$('model-code').textContent=D.lineage[e.target.value];
 document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{answer=Object.keys(D.answers)[+b.dataset.question];render();});
 if($('export-answer'))$('export-answer').onclick=()=>download('copilot_answer.csv',csv(D.answers[answer].rows),'text/csv');
 if($('question-form'))$('question-form').onsubmit=e=>{e.preventDefault();const q=$('question').value.toLowerCase();const idx=q.includes('mismatch')||q.includes('variance')||q.includes('reconcil')?1:q.includes('renew')?2:q.includes('retention')||q.includes('nrr')||q.includes('grr')?6:q.includes('declin')||q.includes('risk')||q.includes('drop')?5:q.includes('feature')||q.includes('adoption')||q.includes('mid-market')?4:q.includes('tier')||q.includes('segment')?3:q.includes('total')||q.includes('overall')||q.includes('our arr')||q.includes('current arr')?0:-1;if(idx<0){$('question-notice').innerHTML='<div class="explainer">This question is outside the supported demo topics. Choose a suggestion; no answer was invented.</div>';return;}answer=Object.keys(D.answers)[idx];render();};
}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('segment').onchange=e=>{tier=e.target.value;render()};$('tour-start').onclick=()=>{tour=0;go(tours[0].view)};$('close-detail').onclick=()=>$('detail').close();if(headings[location.hash.slice(1)])view=location.hash.slice(1);render();
